{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Pamiparib, the closest structural analogue with a tetracyclic fused-lactam PARP-inhibitor core and a fluorinated aromatic ring, showed high bioavailability with near-complete absorption in humans, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CP-409,092, which shares the methylaminomethylphenyl group and a lactam-containing heterocycle, had a relative bioavailability of 69% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vonoprazan, a moderately similar fused heteroaromatic drug, had an estimated human bioavailability of 36%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Milrinone, a heteroaromatic drug with moderate structural similarity, had a mean absolute bioavailability of 92% in healthy men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Safinamide, despite lower structural similarity, showed 95% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The only low-F analogue had ~10% bioavailability due to very slow absorption of a water-soluble non-metabolized TC; its low transferability and different absorption mechanism do not outweigh the high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High. The closest analogue pamiparib has near-complete absorption in humans, and multiple moderately similar drugs have F values of 36-95%, all above the 20% threshold. The single low-F analogue is structurally distant and its poor absorption is attributed to very slow gut uptake of a water-soluble non-metabolized TC, so it does not transfer to the query. Thus F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself in the provided evidence.",
    "Morgan similarities are low (0.19-0.28), limiting quantitative transferability.",
    "The low-F analogue C10 has a different absorption mechanism, making its relevance uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

